+// Número de factura SSS-AAAA-NNNNNN (brain de empresa: estandares/documentos-fiscales.md).
+// Un valor fuera de rango es un error: nunca se trunca ni se ajusta.
+export function numeroFactura(sucursal, gestion, correlativo) {
+  if (!Number.isInteger(sucursal) || sucursal < 1 || sucursal > 999)
+    throw new RangeError("Sucursal inválida: debe ser un entero de 1 a 999");
+  if (!Number.isInteger(gestion) || gestion < 1000 || gestion > 9999)
+    throw new RangeError("Gestión inválida: debe ser un año de 4 dígitos");
+  if (!Number.isInteger(correlativo) || correlativo < 1 || correlativo > 999999)
+    throw new RangeError("Correlativo inválido: debe ser un entero de 1 a 999999");
+  return `${String(sucursal).padStart(3, "0")}-${gestion}-${String(correlativo).padStart(6, "0")}`;
+}
